//! String similarity helpers used for "did you mean" suggestions.

use std::cmp::{max, min};

/// Jaro similarity between two strings (character based).
pub fn jaro(a: &str, b: &str) -> f64 {
    let a_len = a.chars().count();
    let b_len = b.chars().count();

    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    } else if a_len == 1 && b_len == 1 {
        return if a == b { 1.0 } else { 0.0 };
    }

    let search_range = (max(a_len, b_len) / 2) - 1;

    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0;
    let mut transpositions = 0.0;
    let mut b_match_index = 0;

    for (i, a_char) in a.chars().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = min(b_len - 1, i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, b_char) in b.chars().enumerate() {
            if min_bound <= j && j <= max_bound && a_char == b_char && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }

    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

/// Jaro-Winkler similarity (common prefix is not length limited).
pub fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);

    let prefix_length = a
        .chars()
        .zip(b.chars())
        .take_while(|(ac, bc)| ac == bc)
        .count();

    let jw = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));

    if jw <= 1.0 {
        jw
    } else {
        1.0
    }
}

/// Returns the best candidate with a similarity above 0.8, if any.
pub fn did_you_mean<'a, I>(value: &str, candidates: I) -> Option<&'a str>
where
    I: IntoIterator<Item = &'a str>,
{
    let mut best: Option<(f64, &'a str)> = None;
    for candidate in candidates {
        let confidence = jaro_winkler(value, candidate);
        if confidence > 0.8 && best.map_or(true, |(c, _)| c < confidence) {
            best = Some((confidence, candidate));
        }
    }
    best.map(|(_, c)| c)
}
