//! Greedy text wrapping with hyphen splitting (used for help texts).

use unicode_width::{UnicodeWidthChar, UnicodeWidthStr};

/// Returns the possible split points of a word: (head, tail) pairs, smallest head first,
/// followed by the "no split" alternative.
fn hyphen_splits(word: &str) -> Vec<(&str, &str)> {
    let mut splits = Vec::new();
    let mut char_indices = word.char_indices();
    let mut prev = match char_indices.next() {
        None => return vec![(word, "")],
        Some((_, ch)) => ch,
    };
    let (mut idx, mut cur) = match char_indices.next() {
        None => return vec![(word, "")],
        Some((idx, cur)) => (idx, cur),
    };
    for (i, next) in char_indices {
        if prev.is_alphanumeric() && cur == '-' && next.is_alphanumeric() {
            let (head, tail) = word.split_at(idx + 1);
            splits.push((head, tail));
        }
        prev = cur;
        idx = i;
        cur = next;
    }
    splits.push((word, ""));
    splits
}

/// Wraps a single line (no newlines inside) into lines of at most `width` columns.
/// Words longer than the width are not broken.
pub fn wrap_line(source: &str, width: usize) -> Vec<String> {
    let mut result = Vec::new();
    let mut start = 0usize;
    let mut split = 0usize;
    let mut split_len = 0usize;
    let mut line_width = 0usize;
    let mut line_width_at_split = 0usize;
    let mut in_whitespace = false;

    for (idx, ch) in source.char_indices() {
        let char_width = ch.width().unwrap_or(0);
        let char_len = ch.len_utf8();

        if ch.is_whitespace() {
            if in_whitespace {
                split_len += char_len;
            } else {
                split = idx;
                split_len = char_len;
            }
            line_width_at_split = line_width + char_width;
            in_whitespace = true;
        } else if line_width + char_width > width {
            in_whitespace = false;
            let remaining_text = &source[split + split_len..];
            let final_word = match remaining_text.find(|c: char| c.is_whitespace()) {
                Some(i) => &remaining_text[..i],
                None => remaining_text,
            };

            let splits = hyphen_splits(final_word);
            for &(head, _) in splits.iter().rev() {
                if line_width_at_split + head.width() <= width {
                    split += split_len + head.len();
                    split_len = 0;
                    break;
                }
            }

            if start >= split {
                // The word is too big for a single line; add the smallest split.
                split = start + splits[0].0.len();
                split_len = 0;
                line_width_at_split = line_width;
            }

            if start < split {
                result.push(source[start..split].to_string());
                start = split + split_len;
                line_width = line_width.wrapping_sub(line_width_at_split).wrapping_add(char_width);
                continue;
            }
        } else {
            in_whitespace = false;
        }
        line_width += char_width;
    }

    if start < source.len() {
        result.push(source[start..].to_string());
    }

    result
}

/// Wraps every line of `text` separately and joins the result with newlines.
pub fn wrap_help(text: &str, width: usize) -> String {
    text.lines()
        .map(|line| wrap_line(line, width).join("\n"))
        .collect::<Vec<_>>()
        .join("\n")
}
EOF
