{"command":"cat > /workspace/src/cli.rs <<'EOF'
//! Command line parsing. Mimics the behaviour and messages of a classic
//! "FLAGS/OPTIONS/SUBCOMMANDS" style argument parser.

use std::collections::HashMap;
use std::io::IsTerminal;

use unicode_width::UnicodeWidthStr;

use crate::strsim::did_you_mean;
use crate::wrap::wrap_help;

pub const APP_NAME: &str = "bartib";
pub const APP_VERSION: &str = "1.1.0";
pub const APP_AUTHOR: &str = "Nikolas Schmidt-Voigt <nikolas.schmidt-voigt@posteo.de>";
pub const APP_ABOUT: &str = "A simple timetracker";
pub const APP_AFTER_HELP: &str = "To get help for a specific subcommand, run `bartib [SUBCOMMAND] --help`.\nTo get started, view the `start` help with `bartib start --help`";

const TERM_WIDTH: usize = 120;
const TAB: &str = "    ";

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Flag,
    Opt,
    Pos,
}

#[derive(Clone, Copy)]
pub struct ArgDef {
    pub name: &'static str,
    pub kind: Kind,
    pub short: Option<char>,
    pub long: Option<&'static str>,
    pub value_name: Option<&'static str>,
    pub required: bool,
    pub default: Option<&'static str>,
    pub env: Option<&'static str>,
    pub conflicts: &'static [&'static str],
    pub help: &'static str,
}

impl ArgDef {
    const fn base(name: &'static str, kind: Kind, help: &'static str) -> ArgDef {
        ArgDef {
            name,
            kind,
            short: None,
            long: None,
            value_name: None,
            required: false,
            default: None,
            env: None,
            conflicts: &[],
            help,
        }
    }

    pub const fn flag(name: &'static str, short: Option<char>, long: &'static str, help: &'static str) -> ArgDef {
        let mut a = ArgDef::base(name, Kind::Flag, help);
        a.short = short;
        a.long = Some(long);
        a
    }

    pub const fn opt(
        name: &'static str,
        short: Option<char>,
        long: Option<&'static str>,
        value_name: Option<&'static str>,
        help: &'static str,
    ) -> ArgDef {
        let mut a = ArgDef::base(name, Kind::Opt, help);
        a.short = short;
        a.long = long;
        a.value_name = value_name;
        a
    }

    pub const fn pos(name: &'static str, help: &'static str) -> ArgDef {
        ArgDef::base(name, Kind::Pos, help)
    }

    pub const fn required(mut self) -> ArgDef {
        self.required = true;
        self
    }

    pub const fn default(mut self, d: &'static str) -> ArgDef {
        self.default = Some(d);
        self
    }

    pub const fn env(mut self, e: &'static str) -> ArgDef {
        self.env = Some(e);
        self
    }

    pub const fn conflicts(mut self, c: &'static [&'static str]) -> ArgDef {
        self.conflicts = c;
        self
    }

    pub fn takes_value(&self) -> bool {
        self.kind != Kind::Flag
    }

    pub fn has_switch(&self) -> bool {
        self.kind != Kind::Pos
    }

    fn val_display(&self) -> String {
        format!("<{}>", self.value_name.unwrap_or(self.name))
    }

    /// The representation used in usage strings and error messages.
    pub fn display(&self) -> String {
        match self.kind {
            Kind::Flag => {
                if let Some(l) = self.long {
                    format!("--{}", l)
                } else {
                    format!("-{}", self.short.unwrap_or(' '))
                }
            }
            Kind::Opt => {
                if let Some(l) = self.long {
                    format!("--{} {}", l, self.val_display())
                } else {
                    format!("-{} {}", self.short.unwrap_or(' '), self.val_display())
                }
            }
            Kind::Pos => self.val_display(),
        }
    }
}

const HELP_FLAG: ArgDef = ArgDef::flag("help", Some('h'), "help", "Prints help information");
const VERSION_FLAG: ArgDef = ArgDef::flag("version", Some('V'), "version", "Prints version information");

pub struct CmdDef {
    pub name: &'static str,
    pub about: &'static str,
    pub args: &'static [ArgDef],
}

#[derive(Default, Debug)]
pub struct Matched {
    pub name: String,
    pub occurrences: usize,
    pub values: Vec<String>,
}

#[derive(Default, Debug)]
pub struct Matches {
    pub args: Vec<Matched>,
    pub subcommand: Option<(String, Box<Matches>)>,
}

impl Matches {
    fn get_mut(&mut self, name: &str) -> &mut Matched {
        if let Some(i) = self.args.iter().position(|m| m.name == name) {
            &mut self.args[i]
        } else {
            self.args.push(Matched {
                name: name.to_string(),
                ..Default::default()
            });
            self.args.last_mut().unwrap()
        }
    }

    fn get(&self, name: &str) -> Option<&Matched> {
        self.args.iter().find(|m| m.name == name)
    }

    fn contains(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    pub fn is_present(&self, name: &str) -> bool {
        self.get(name).is_some()
    }

    pub fn value_of(&self, name: &str) -> Option<&str> {
        self.get(name).and_then(|m| m.values.first()).map(|s| s.as_str())
    }
}

/// The outcome of parsing: either matches or something to print and an exit code.
pub enum Outcome {
    Matches(Matches),
    /// Text to print to stdout followed by a newline, then exit 0.
    Info(String),
    /// Text to print to stderr followed by a newline, then exit 1.
    Failure(String),
}

type ParseResult<T> = Result<T, Outcome>;

struct Colorizer {
    enabled: bool,
}

impl Colorizer {
    fn new() -> Colorizer {
        let is_tty = std::io::stderr().is_terminal();
        let dumb = std::env::var("TERM").ok().as_deref() == Some("dumb");
        Colorizer {
            enabled: is_tty && !dumb,
        }
    }

    fn error(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[1;31m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }

    fn warning(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[33m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }

    fn good(&self, s: &str) -> String {
        if self.enabled {
            format!("\x1b[32m{}\x1b[0m", s)
        } else {
            s.to_string()
        }
    }
}

/// Always colored "good" formatting (used in suggestion suffixes).
fn always_good(s: &str) -> String {
    format!("\x1b[32m{}\x1b[0m", s)
}

pub struct App {
    pub top: CmdDef,
    pub subcommands: Vec<CmdDef>,
    bin_name: String,
    colorizer: Colorizer,
}

struct Level<'a> {
    cmd: &'a CmdDef,
    is_top: bool,
    bin_name: String,
}

impl<'a> Level<'a> {
    fn all_args(&self) -> Vec<ArgDef> {
        let mut v: Vec<ArgDef> = self.cmd.args.to_vec();
        v.push(HELP_FLAG);
        if self.is_top {
            v.push(VERSION_FLAG);
        }
        v
    }

    fn flags(&self) -> Vec<ArgDef> {
        self.all_args().into_iter().filter(|a| a.kind == Kind::Flag).collect()
    }

    fn opts(&self) -> Vec<ArgDef> {
        self.all_args().into_iter().filter(|a| a.kind == Kind::Opt).collect()
    }

    fn positionals(&self) -> Vec<ArgDef> {
        self.all_args().into_iter().filter(|a| a.kind == Kind::Pos).collect()
    }

    fn find(&self, name: &str) -> Option<ArgDef> {
        self.all_args().into_iter().find(|a| a.name == name)
    }

    fn find_by_long(&self, long: &str) -> Option<ArgDef> {
        self.all_args().into_iter().find(|a| a.has_switch() && a.long == Some(long))
    }

    fn find_by_short(&self, short: char) -> Option<ArgDef> {
        self.all_args().into_iter().find(|a| a.has_switch() && a.short == Some(short))
    }

    /// Sorted, deduplicated usage items for the given argument names.
    fn required_usage_from(&self, names: &[&str]) -> Vec<String> {
        let mut names: Vec<&str> = names.to_vec();
        names.sort();
        names.dedup();
        let mut out = Vec::new();
        for p in self.positionals() {
            if names.contains(&p.name) {
                out.push(p.display());
            }
        }
        for n in &names {
            if let Some(a) = self.find(n) {
                if a.kind != Kind::Pos {
                    out.push(a.display());
                }
            }
        }
        out
    }

    fn help_usage(&self) -> String {
        let mut usage = self.bin_name.clone();
        let reqs: Vec<&str> = self.cmd.args.iter().filter(|a| a.required).map(|a| a.name).collect();
        let req_string: String = self
            .required_usage_from(&reqs)
            .iter()
            .map(|s| format!(" {}", s))
            .collect();
        let needs_flags_tag = self
            .flags()
            .iter()
            .any(|f| f.long != Some("help") && f.long != Some("version"));
        if needs_flags_tag {
            usage.push_str(" [FLAGS]");
        }
        if self.opts().iter().any(|o| !o.required) {
            usage.push_str(" [OPTIONS]");
        }
        usage.push_str(&req_string);
        let not_req: Vec<ArgDef> = self.positionals().into_iter().filter(|p| !p.required).collect();
        if !not_req.is_empty() {
            if not_req.len() == 1 {
                usage.push_str(&format!(" [{}]", not_req[0].value_name.unwrap_or(not_req[0].name)));
            } else {
                usage.push_str(" [ARGS]");
            }
        }
        if self.is_top {
            usage.push_str(" <SUBCOMMAND>");
        }
        usage
    }

    fn smart_usage(&self, used: &[&str]) -> String {
        let mut names: Vec<&str> = self.cmd.args.iter().filter(|a| a.required).map(|a| a.name).collect();
        names.extend_from_slice(used);
        let r_string: String = self
            .required_usage_from(&names)
            .iter()
            .map(|s| format!(" {}", s))
            .collect();
        format!("{}{}", self.bin_name, r_string)
    }

    fn error_usage(&self, matcher: &Matches) -> String {
        let used: Vec<&str> = matcher
            .args
            .iter()
            .filter(|m| match self.find(&m.name) {
                Some(a) => match a.kind {
                    Kind::Opt => !a.required,
                    Kind::Pos => false,
                    Kind::Flag => true,
                },
                None => true,
            })
            .map(|m| m.name.as_str())
            .collect();
        let usage = if used.is_empty() {
            self.help_usage()
        } else {
            self.smart_usage(&used)
        };
        format!("USAGE:\n    {}", usage)
    }
}

impl App {
    pub fn new(top: CmdDef, subcommands: Vec<CmdDef>) -> App {
        let bin_name = std::env::args_os()
            .next()
            .and_then(|a| {
                std::path::Path::new(&a)
                    .file_name()
                    .and_then(|f| f.to_str().map(|s| s.to_string()))
            })
            .unwrap_or_else(|| APP_NAME.to_string());
        App {
            top,
            subcommands,
            bin_name,
            colorizer: Colorizer::new(),
        }
    }

    fn find_subcommand(&self, name: &str) -> Option<&CmdDef> {
        self.subcommands.iter().find(|s| s.name == name)
    }

    fn subcommand_names(&self) -> Vec<&str> {
        let mut v: Vec<&str> = self.subcommands.iter().map(|s| s.name).collect();
        v.push("help");
        v
    }

    pub fn parse(&self, args: Vec<String>) -> Outcome {
        let level = Level {
            cmd: &self.top,
            is_top: true,
            bin_name: self.bin_name.clone(),
        };
        match self.parse_level(&level, &args, 0) {
            Ok(m) => Outcome::Matches(m),
            Err(o) => o,
        }
    }

    // ----- errors -------------------------------------------------------

    fn err_unknown_argument(&self, arg: &str, suffix: &str, usage: &str) -> Outcome {
        let c = &self.colorizer;
        Outcome::Failure(format!(
            "{} Found argument '{}' which wasn't expected, or isn't valid in this context{}\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(arg),
            if suffix.is_empty() {
                "\n".to_string()
            } else {
                format!("{}\n", suffix)
            },
            usage,
            c.good("--help")
        ))
    }

    fn err_invalid_subcommand(&self, subcmd: &str, dym: &str, usage: &str) -> Outcome {
        let c = &self.colorizer;
        Outcome::Failure(format!(
            "{} The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} {} {}'\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(subcmd),
            c.good(dym),
            self.bin_name,
            c.good("--"),
            subcmd,
            usage,
            c.good("--help")
        ))
    }

    fn err_unrecognized_subcommand(&self, subcmd: &str) -> Outcome {
        let c = &self.colorizer;
        Outcome::Failure(format!(
            "{} The subcommand '{}' wasn't recognized\n\n{}\n\t{} help <subcommands>...\n\nFor more information try {}",
            c.error("error:"),
            c.warning(subcmd),
            c.warning("USAGE:"),
            self.bin_name,
            c.good("--help")
        ))
    }

    fn err_empty_value(&self, arg: &ArgDef, usage: &str) -> Outcome {
        let c = &self.colorizer;
        Outcome::Failure(format!(
            "{} The argument '{}' requires a value but none was supplied\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(&arg.display()),
            usage,
            c.good("--help")
        ))
    }

    fn err_missing_required(&self, reqs: &[String], usage: &str) -> Outcome {
        let c = &self.colorizer;
        let req_args: String = reqs.iter().map(|r| format!("\n    {}", c.error(r))).collect();
        Outcome::Failure(format!(
            "{} The following required arguments were not provided:{}\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            req_args,
            usage,
            c.good("--help")
        ))
    }

    fn err_conflict(&self, arg: &ArgDef, other: Option<String>, usage: &str) -> Outcome {
        let c = &self.colorizer;
        Outcome::Failure(format!(
            "{} The argument '{}' cannot be used with {}\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(&arg.display()),
            match other {
                Some(o) => c.warning(&format!("'{}'", o)),
                None => "one or more of the other specified arguments".to_string(),
            },
            usage,
            c.good("--help")
        ))
    }

    fn err_multiple(&self, arg: &ArgDef, usage: &str) -> Outcome {
        let c = &self.colorizer;
        Outcome::Failure(format!(
            "{} The argument '{}' was provided more than once, but cannot be used multiple times\n\n{}\n\nFor more information try {}",
            c.error("error:"),
            c.warning(&arg.display()),
            usage,
            c.good("--help")
        ))
    }

    // ----- help -------------------------------------------------------------

    fn version_string(&self) -> String {
        if self.bin_name.contains(' ') {
            format!("{} {}", self.bin_name.replace(' ', "-"), APP_VERSION)
        } else {
            format!("{} {}", APP_NAME, APP_VERSION)
        }
    }

    fn write_arg_help(&self, out: &mut String, a: &ArgDef, longest: usize) {
        out.push_str(TAB);
        if let Some(s) = a.short {
            out.push('-');
            out.push(s);
        } else if a.has_switch() {
            out.push_str(TAB);
        }
        if a.has_switch() {
            if a.takes_value() {
                if let Some(l) = a.long {
                    if a.short.is_some() {
                        out.push_str(", ");
                    }
                    out.push_str("--");
                    out.push_str(l);
                }
                out.push(' ');
            } else if let Some(l) = a.long {
                if a.short.is_some() {
                    out.push_str(", ");
                }
                out.push_str("--");
                out.push_str(l);
                out.push_str(&" ".repeat((longest + 4).saturating_sub(l.width() + 2)));
            } else {
                out.push_str(&" ".repeat(longest + 6));
            }
        }
        if a.takes_value() {
            if a.has_switch() {
                out.push_str(&a.val_display());
            } else {
                out.push_str(&a.display());
            }
        }
        if a.has_switch() {
            let self_len = a.display().width();
            let mut spcs = longest.saturating_sub(self_len);
            if a.long.is_some() {
                spcs += 4;
            } else {
                spcs += 8;
            }
            out.push_str(&" ".repeat(spcs));
        } else {
            out.push_str(&" ".repeat((longest + 4).saturating_sub(a.display().width())));
        }

        // spec vals
        let mut spec_vals: Vec<String> = Vec::new();
        if let Some(env) = a.env {
            let val = std::env::var_os(env)
                .map(|v| v.to_string_lossy().into_owned())
                .unwrap_or_default();
            spec_vals.push(format!(" [env: {}={}]", env, val));
        }
        if let Some(d) = a.default {
            spec_vals.push(format!(" [default: {}]", d));
        }
        let spec_vals = spec_vals.join(" ");
        self.write_help_text(out, a.help, &spec_vals, longest, a.has_switch());
    }

    fn write_help_text(&self, out: &mut String, h: &str, spec_vals: &str, longest: usize, has_switch: bool) {
        let mut help = format!("{}{}", h, spec_vals);
        let spcs = longest + 12;
        let too_long = spcs + h.width() + spec_vals.width() >= TERM_WIDTH;
        if too_long && spcs <= TERM_WIDTH {
            help = wrap_help(&help, TERM_WIDTH - spcs);
        }
        let mut lines = help.lines();
        if let Some(first) = lines.next() {
            out.push_str(first);
        }
        for part in lines {
            out.push('\n');
            if has_switch {
                out.push_str(&" ".repeat(longest + 12));
            } else {
                out.push_str(&" ".repeat(longest + 8));
            }
            out.push_str(part);
        }
    }

    fn write_args(&self, out: &mut String, args: &[ArgDef], sort: bool) {
        let mut longest = 2;
        for a in args {
            longest = std::cmp::max(longest, a.display().width());
        }
        let mut sorted: Vec<&ArgDef> = args.iter().collect();
        if sort {
            sorted.sort_by(|a, b| a.name.cmp(b.name));
        }
        let mut first = true;
        for a in sorted {
            if !first {
                out.push('\n');
            }
            first = false;
            self.write_arg_help(out, a, longest);
        }
    }

    fn help_text(&self, level: &Level) -> String {
        let mut out = String::new();
        if level.is_top {
            out.push_str(&self.version_string());
            out.push('\n');
            out.push_str(APP_AUTHOR);
            out.push('\n');
        } else {
            out.push_str(&level.bin_name.replace(' ', "-"));
            out.push_str(" \n");
        }
        out.push_str(level.cmd.about);
        out.push('\n');
        out.push_str("\nUSAGE:\n");
        out.push_str(TAB);
        out.push_str(&level.help_usage());
        out.push_str("\n\n");

        let flags = level.flags();
        let opts = level.opts();
        let pos = level.positionals();
        let mut first = true;
        if !flags.is_empty() {
            out.push_str("FLAGS:\n");
            self.write_args(&mut out, &flags, true);
            first = false;
        }
        if !opts.is_empty() {
            if !first {
                out.push_str("\n\n");
            }
            out.push_str("OPTIONS:\n");
            self.write_args(&mut out, &opts, true);
            first = false;
        }
        if !pos.is_empty() {
            if !first {
                out.push_str("\n\n");
            }
            out.push_str("ARGS:\n");
            self.write_args(&mut out, &pos, false);
            first = false;
        }
        if level.is_top {
            if !first {
                out.push_str("\n\n");
            }
            out.push_str("SUBCOMMANDS:\n");
            let mut names: Vec<(&str, &str)> = self.subcommands.iter().map(|s| (s.name, s.about)).collect();
            names.push(("help", "Prints this message or the help of the given subcommand(s)"));
            names.sort();
            let longest = names.iter().map(|(n, _)| n.width()).max().unwrap_or(2).max(2);
            let mut first_sc = true;
            for (n, about) in names {
                if !first_sc {
                    out.push('\n');
                }
                first_sc = false;
                out.push_str(TAB);
                out.push_str(n);
                out.push_str(&" ".repeat(longest + 4 - n.width()));
                self.write_help_text(&mut out, about, "", longest, false);
            }
            out.push_str("\n\n");
            out.push_str(APP_AFTER_HELP);
        }
        out
    }

    fn help_help_text(&self) -> String {
        format!(
            "{}-help \nPrints this message or the help of the given subcommand(s)\n\nUSAGE:\n    {} help [subcommand]...\n\nARGS:\n    <subcommand>...    The subcommand whose help message to display",
            self.bin_name, self.bin_name
        )
    }

    fn parse_help_subcommand(&self, cmds: &[String]) -> Outcome {
        let mut help_help = false;
        let mut sc: Option<&CmdDef> = None; // None = top level
        let mut bin_name = self.bin_name.clone();
        for (i, cmd) in cmds.iter().enumerate() {
            if cmd == "help" {
                help_help = true;
            }
            match sc {
                None => {
                    if cmd == "help" {
                        sc = None;
                        // the help subcommand itself has no subcommands
                        if i == cmds.len() - 1 {
                            break;
                        }
                        // any further name is unknown to the help subcommand
                        return self.err_unrecognized_subcommand(&cmds[i + 1]);
                    } else if let Some(c) = self.find_subcommand(cmd) {
                        sc = Some(c);
                        if i == cmds.len() - 1 {
                            break;
                        }
                    } else {
                        return self.err_unrecognized_subcommand(cmd);
                    }
                }
                Some(_) => {
                    // subcommands have no nested subcommands
                    return self.err_unrecognized_subcommand(cmd);
                }
            }
            bin_name = format!("{} {}", bin_name, cmd);
        }
        if help_help {
            return Outcome::Info(self.help_help_text());
        }
        match sc {
            None => {
                let level = Level {
                    cmd: &self.top,
                    is_top: true,
                    bin_name: self.bin_name.clone(),
                };
                Outcome::Info(self.help_text(&level))
            }
            Some(c) => {
                let level = Level {
                    cmd: c,
                    is_top: false,
                    bin_name: format!("{} {}", bin_name, c.name),
                };
                Outcome::Info(self.help_text(&level))
            }
        }
    }

    // ----- parsing ----------------------------------------------------------

    fn parse_level(&self, level: &Level, args: &[String], start: usize) -> ParseResult<Matches> {
        let mut matcher = Matches::default();
        let mut needs_val_of: Option<ArgDef> = None;
        let mut trailing = false;
        let mut pos_counter = 0usize;
        let positionals = level.positionals();
        let mut idx = start;
        let mut subcmd: Option<&CmdDef> = None;

        while idx < args.len() {
            let arg = &args[idx];
            idx += 1;
            let starts_new_arg = arg.starts_with('-') && arg.len() != 1;

            if !trailing && arg == "--" && starts_new_arg {
                trailing = true;
                continue;
            }

            if !trailing {
                if needs_val_of.is_none() && level.is_top {
                    if arg == "help" {
                        return Err(self.parse_help_subcommand(&args[idx..]));
                    }
                    if let Some(sc) = self.find_subcommand(arg) {
                        subcmd = Some(sc);
                        break;
                    }
                }

                if starts_new_arg {
                    if arg.starts_with("--") {
                        needs_val_of = self.parse_long_arg(level, &mut matcher, arg)?;
                    } else {
                        needs_val_of = self.parse_short_arg(level, &mut matcher, arg)?;
                    }
                    continue;
                } else if let Some(opt) = needs_val_of {
                    matcher.get_mut(opt.name).values.push(arg.clone());
                    needs_val_of = None;
                    continue;
                }
            }

            // positional argument or something unknown
            if level.is_top {
                if let Some(c) = did_you_mean(arg, self.subcommand_names()) {
                    let usage = level.error_usage(&matcher);
                    return Err(self.err_invalid_subcommand(arg, c, &usage));
                }
            }
            if let Some(p) = positionals.get(pos_counter) {
                let m = matcher.get_mut(p.name);
                m.occurrences += 1;
                m.values.push(arg.clone());
                pos_counter += 1;
                needs_val_of = None;
                continue;
            }
            let usage = level.error_usage(&matcher);
            return Err(self.err_unknown_argument(arg, "", &usage));
        }

        if let Some(sc) = subcmd {
            let sub_level = Level {
                cmd: sc,
                is_top: false,
                bin_name: format!("{} {}", level.bin_name, sc.name),
            };
            let sub_matches = self.parse_level(&sub_level, args, idx)?;
            matcher.subcommand = Some((sc.name.to_string(), Box::new(sub_matches)));
        } else if level.is_top {
            return Err(Outcome::Failure(self.help_text(level)));
        }

        self.validate(level, &mut matcher, needs_val_of)?;
        Ok(matcher)
    }

    fn parse_long_arg(&self, level: &Level, matcher: &mut Matches, full_arg: &str) -> ParseResult<Option<ArgDef>> {
        let stripped = full_arg.trim_start_matches('-');
        let (name, val) = match stripped.find('=') {
            Some(i) => (&stripped[..i], Some(&stripped[i + 1..])),
            None => (stripped, None),
        };
        if let Some(a) = level.find_by_long(name) {
            if a.kind == Kind::Opt {
                return self.parse_opt(matcher, &a, val);
            }
            self.check_help_version(level, &a)?;
            matcher.get_mut(a.name).occurrences += 1;
            return Ok(None);
        }
        // suggestion
        let longs: Vec<&str> = level.all_args().iter().filter_map(|a| a.long).collect();
        let suffix;
        if let Some(c) = did_you_mean(name, longs.iter().copied()) {
            if let Some(a) = level.find_by_long(c) {
                matcher.get_mut(a.name).occurrences += 1;
            }
            suffix = format!("\n\tDid you mean {}{}?", always_good("--"), always_good(c));
        } else {
            suffix = String::new();
        }
        let usage = level.error_usage(matcher);
        Err(self.err_unknown_argument(&format!("--{}", name), &suffix, &usage))
    }

    fn parse_short_arg(&self, level: &Level, matcher: &mut Matches, full_arg: &str) -> ParseResult<Option<ArgDef>> {
        let arg = full_arg.trim_start_matches('-');
        let mut ret = None;
        for (i, c) in arg.char_indices() {
            if let Some(a) = level.find_by_short(c) {
                if a.kind == Kind::Opt {
                    let rest = &arg[i + c.len_utf8()..];
                    let val = if rest.is_empty() { None } else { Some(rest) };
                    return self.parse_opt(matcher, &a, val);
                }
                self.check_help_version(level, &a)?;
                matcher.get_mut(a.name).occurrences += 1;
                ret = None;
            } else {
                let usage = level.error_usage(matcher);
                return Err(self.err_unknown_argument(&format!("-{}", c), "", &usage));
            }
        }
        Ok(ret)
    }

    fn parse_opt(&self, matcher: &mut Matches, a: &ArgDef, val: Option<&str>) -> ParseResult<Option<ArgDef>> {
        match val {
            Some(v) => {
                let v = v.trim_start_matches('=');
                let m = matcher.get_mut(a.name);
                m.values.push(v.to_string());
                m.occurrences += 1;
                Ok(None)
            }
            None => {
                matcher.get_mut(a.name).occurrences += 1;
                Ok(Some(*a))
            }
        }
    }

    fn check_help_version(&self, level: &Level, a: &ArgDef) -> ParseResult<()> {
        if a.name == "help" {
            return Err(Outcome::Info(self.help_text(level)));
        }
        if a.name == "version" && level.is_top {
            return Err(Outcome::Info(self.version_string()));
        }
        Ok(())
    }

    fn validate_required(&self, level: &Level, matcher: &Matches) -> ParseResult<()> {
        let missing: Vec<&str> = level
            .cmd
            .args
            .iter()
            .filter(|a| a.required && !matcher.contains(a.name))
            .map(|a| a.name)
            .collect();
        if missing.is_empty() {
            return Ok(());
        }
        let reqs = level.required_usage_from(&missing);
        let usage = level.error_usage(matcher);
        Err(self.err_missing_required(&reqs, &usage))
    }

    fn validate(&self, level: &Level, matcher: &mut Matches, needs_val_of: Option<ArgDef>) -> ParseResult<()> {
        // environment variables
        for a in level.all_args() {
            if let Some(env) = a.env {
                let has_vals = matcher.get(a.name).map(|m| !m.values.is_empty()).unwrap_or(false);
                if !has_vals {
                    if let Some(v) = std::env::var_os(env) {
                        let m = matcher.get_mut(a.name);
                        m.values.push(v.to_string_lossy().into_owned());
                        m.occurrences = 1;
                    }
                }
            }
        }
        // defaults
        for a in level.all_args() {
            if let Some(d) = a.default {
                let has_vals = matcher.get(a.name).map(|m| !m.values.is_empty()).unwrap_or(false);
                if !has_vals {
                    matcher.get_mut(a.name).values.push(d.to_string());
                }
            }
        }

        let mut reqs_validated = false;
        if let Some(opt) = needs_val_of {
            self.validate_required(level, matcher)?;
            reqs_validated = true;
            let empty = matcher.get(opt.name).map(|m| m.values.is_empty()).unwrap_or(true);
            if empty {
                let usage = level.error_usage(matcher);
                return Err(self.err_empty_value(&opt, &usage));
            }
        }

        // conflicts
        let mut blacklist: Vec<&str> = Vec::new();
        for m in &matcher.args {
            if let Some(a) = level.find(&m.name) {
                for conf in a.conflicts {
                    if matcher.contains(conf) {
                        blacklist.push(conf);
                    }
                }
            }
        }
        for name in blacklist {
            let should_err = matcher.get(name).map(|m| m.occurrences > 0).unwrap_or(false);
            if should_err {
                let arg = level.find(name).unwrap();
                let mut other: Option<String> = None;
                for m in &matcher.args {
                    if let Some(a) = level.find(&m.name) {
                        if a.conflicts.contains(&name) {
                            other = Some(a.display());
                        }
                    }
                }
                let usage = level.error_usage(matcher);
                return Err(self.err_conflict(&arg, other, &usage));
            }
        }

        if !reqs_validated {
            self.validate_required(level, matcher)?;
        }

        // matched args
        for m in &matcher.args {
            if let Some(a) = level.find(&m.name) {
                if a.kind == Kind::Opt && m.values.is_empty() {
                    let usage = level.error_usage(matcher);
                    return Err(self.err_empty_value(&a, &usage));
                }
                if m.occurrences > 1 {
                    let usage = level.error_usage(matcher);
                    return Err(self.err_multiple(&a, &usage));
                }
            }
        }
        Ok(())
    }
}

/// Helper to build a lookup of environment variables (unused placeholder to keep HashMap import).
#[allow(dead_code)]
fn _unused() -> HashMap<String, String> {
    HashMap::new()
}
