//! Activities and their textual representation in the log file.

use std::fmt;

use chrono::{DurationRound, NaiveDateTime, TimeDelta};

pub const DATETIME_FORMAT: &str = "%Y-%m-%d %H:%M";
const DATETIME_FORMAT_SECONDS: &str = "%Y-%m-%d %H:%M:%S";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Activity {
    pub start: NaiveDateTime,
    pub end: Option<NaiveDateTime>,
    pub project: String,
    pub description: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ActivityError {
    GeneralParseError,
    DateTimeParseError,
}

impl fmt::Display for ActivityError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ActivityError::GeneralParseError => write!(f, "could not parse activity"),
            ActivityError::DateTimeParseError => write!(f, "could not parse date or time of activity"),
        }
    }
}

impl Activity {
    pub fn start(project: String, description: String, start: NaiveDateTime) -> Activity {
        Activity {
            start,
            end: None,
            project,
            description,
        }
    }

    pub fn is_stopped(&self) -> bool {
        self.end.is_some()
    }

    pub fn stop(&mut self, time: NaiveDateTime) {
        self.end = Some(time);
    }

    /// Duration of the activity; running activities are measured up to `now`.
    pub fn duration(&self, now: NaiveDateTime) -> TimeDelta {
        self.end.unwrap_or(now) - self.start
    }

    pub fn starts_and_ends_on_different_days(&self) -> bool {
        match self.end {
            Some(end) => end.date() != self.start.date(),
            None => false,
        }
    }

    /// Parses a single line of the log file.
    pub fn parse(line: &str) -> Result<Activity, ActivityError> {
        let mut parts: Vec<&str> = line.split('|').collect();
        if parts.last() == Some(&"") {
            parts.pop();
        }
        if parts.len() < 2 {
            return Err(ActivityError::GeneralParseError);
        }
        let time_part = parts[0];
        let project = parts[1].trim().to_string();
        let description = parts.get(2).map(|d| d.trim()).unwrap_or("").to_string();

        let times: Vec<&str> = time_part.split(" - ").collect();
        let start = parse_datetime(times[0].trim())?;
        let end = match times.get(1) {
            Some(e) => Some(parse_datetime(e.trim())?),
            None => None,
        };

        Ok(Activity {
            start,
            end,
            project,
            description,
        })
    }
}

impl fmt::Display for Activity {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.end {
            Some(end) => write!(
                f,
                "{} - {} | {} | {}",
                self.start.format(DATETIME_FORMAT),
                end.format(DATETIME_FORMAT),
                self.project,
                self.description
            ),
            None => write!(
                f,
                "{} | {} | {}",
                self.start.format(DATETIME_FORMAT),
                self.project,
                self.description
            ),
        }
    }
}

fn parse_datetime(s: &str) -> Result<NaiveDateTime, ActivityError> {
    if let Ok(dt) = NaiveDateTime::parse_from_str(s, DATETIME_FORMAT_SECONDS) {
        eprintln!(
            "WARNING: Bartib log encountered timestamps with minute precision.\nThis version of Bartib has been compiled with second precision"
        );
        return Ok(dt.duration_round(TimeDelta::minutes(1)).unwrap_or(dt));
    }
    NaiveDateTime::parse_from_str(s, DATETIME_FORMAT).map_err(|_| ActivityError::DateTimeParseError)
}

/// Formats a duration as e.g. "<1m", "05m", "1h 05m".
pub fn format_duration(d: TimeDelta) -> String {
    let minutes = d.num_minutes();
    if minutes < 1 {
        return "<1m".to_string();
    }
    let hours = minutes / 60;
    let mins = minutes % 60;
    if hours > 0 {
        format!("{}h {:02}m", hours, mins)
    } else {
        format!("{:02}m", mins)
    }
}

/// Rounds a timestamp to the nearest multiple of `interval` (relative to the unix epoch).
pub fn round_datetime(dt: NaiveDateTime, interval: TimeDelta) -> NaiveDateTime {
    let secs = interval.num_seconds();
    let ts = dt.and_utc().timestamp();
    let rounded = (ts as f64 / secs as f64).round() as i64;
    let rounded = rounded.wrapping_mul(secs);
    chrono::DateTime::from_timestamp(rounded, 0)
        .map(|d| d.naive_utc())
        .unwrap_or_default()
}

/// Parses a rounding interval such as "15m" or "2h".
/// Returns `Ok(None)` when the input is silently ignored and `Err(())` when a
/// message should be printed.
pub fn parse_round_interval(s: &str) -> Result<Option<TimeDelta>, ()> {
    let len = s.len();
    let split = len.wrapping_sub(1);
    let num_str = &s[..split];
    let unit = &s[split..];
    let num: i64 = match num_str.parse() {
        Ok(n) => n,
        Err(_) => return Ok(None),
    };
    match unit {
        "m" => Ok(Some(TimeDelta::minutes(num))),
        "h" => Ok(Some(TimeDelta::hours(num))),
        _ => Err(()),
    }
}
