//! Reading and writing the activity log file.

use std::fs::File;
use std::io::{BufRead, BufReader, Write};

use anyhow::{Context, Result};

use crate::activity::{Activity, ActivityError};

/// A single line of the log file together with its parsing result.
#[derive(Debug, Clone)]
pub struct Line {
    pub line_number: usize,
    pub text: String,
    pub activity: Result<Activity, ActivityError>,
    pub modified: bool,
}

impl Line {
    fn parse(line_number: usize, raw: &str) -> Line {
        Line {
            line_number,
            text: raw.trim().to_string(),
            activity: Activity::parse(raw),
            modified: false,
        }
    }

    pub fn for_activity(activity: Activity) -> Line {
        Line {
            line_number: 0,
            text: String::new(),
            activity: Ok(activity),
            modified: true,
        }
    }

    pub fn as_activity_mut(&mut self) -> Option<&mut Activity> {
        self.activity.as_mut().ok()
    }

    pub fn as_activity(&self) -> Option<&Activity> {
        self.activity.as_ref().ok()
    }

    fn output(&self) -> String {
        match (&self.activity, self.modified) {
            (Ok(a), true) => a.to_string(),
            _ => self.text.clone(),
        }
    }
}

pub fn parse_content(content: &str) -> Vec<Line> {
