//! Terminal output helpers: ANSI styles and simple tables.

use std::fmt::Write as _;

/// Non breaking space used to pad table cells.
const PAD: char = '\u{a0}';

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Style {
    None,
    Bold,
    Underline,
    Green,
    Yellow,
    Dimmed,
    Italic,
    DimmedItalic,
    BoldGreen,
}

impl Style {
    fn prefix(self) -> &'static str {
        match self {
            Style::None => "",
            Style::Bold => "\x1b[1m",
            Style::Underline => "\x1b[4m",
            Style::Green => "\x1b[32m",
            Style::Yellow => "\x1b[33m",
            Style::Dimmed => "\x1b[2m",
            Style::Italic => "\x1b[3m",
            Style::DimmedItalic => "\x1b[2;3m",
            Style::BoldGreen => "\x1b[1;32m",
        }
    }

    pub fn paint(self, text: &str) -> String {
        match self {
            Style::None => text.to_string(),
            _ => format!("{}{}\x1b[0m", self.prefix(), text),
        }
    }
}

pub fn char_len(s: &str) -> usize {
    s.chars().count()
}

fn pad(s: &str, width: usize) -> String {
    let mut out = String::from(s);
    for _ in char_len(s)..width {
        out.push(PAD);
    }
    out
}

pub struct Row {
    pub cells: Vec<String>,
    pub style: Style,
}

impl Row {
    pub fn new(cells: Vec<String>) -> Row {
        Row {
            cells,
            style: Style::None,
        }
    }

    pub fn styled(cells: Vec<String>, style: Style) -> Row {
        Row { cells, style }
    }
}

pub struct Group {
    pub title: Option<String>,
    pub rows: Vec<Row>,
}

pub struct Table {
    pub header: Vec<String>,
    pub groups: Vec<Group>,
}

impl Table {
    pub fn new(header: Vec<&str>) -> Table {
        Table {
            header: header.into_iter().map(|s| s.to_string()).collect(),
            groups: Vec::new(),
        }
    }

    pub fn add_rows(&mut self, rows: Vec<Row>) {
        self.groups.push(Group { title: None, rows });
    }

    pub fn add_group(&mut self, title: String, rows: Vec<Row>) {
        self.groups.push(Group {
            title: Some(title),
            rows,
        });
    }

    fn column_widths(&self) -> Vec<usize> {
        let mut widths: Vec<usize> = self.header.iter().map(|h| char_len(h)).collect();
        for g in &self.groups {
            for r in &g.rows {
                for (i, c) in r.cells.iter().enumerate() {
                    if i < widths.len() {
                        widths[i] = widths[i].max(char_len(c));
                    }
                }
            }
        }
        widths
    }

    pub fn render(&self) -> String {
        let widths = self.column_widths();
        let mut out = String::new();
        out.push('\n');
        for (i, h) in self.header.iter().enumerate() {
            out.push_str(&Style::Underline.paint(&pad(h, widths[i])));
            out.push(' ');
        }
        out.push('\n');
        for g in &self.groups {
            if let Some(t) = &g.title {
                out.push('\n');
                out.push_str(&Style::Bold.paint(t));
                out.push('\n');
            }
            for r in &g.rows {
                for (i, c) in r.cells.iter().enumerate() {
                    let _ = write!(out, "{} ", r.style.paint(&pad(c, widths[i])));
                }
                out.push('\n');
            }
        }
        out.push('\n');
        out
    }
}
