//! Implementation of the individual subcommands.

use std::collections::BTreeMap;

use anyhow::{bail, Result};
use chrono::{Datelike, Local, NaiveDate, NaiveDateTime, TimeDelta, Timelike};

use crate::activity::{format_duration, round_datetime, Activity, DATETIME_FORMAT};
use crate::output::{Row, Style, Table};
use crate::storage::{self, Line};

/// The current local time truncated to full minutes.
pub fn now() -> NaiveDateTime {
    let n = Local::now().naive_local();
    n.with_second(0).and_then(|t| t.with_nanosecond(0)).unwrap_or(n)
}

pub fn today() -> NaiveDate {
    Local::now().date_naive()
}

#[derive(Default, Clone)]
pub struct ActivityFilter {
    pub number_of_activities: Option<usize>,
    pub from_date: Option<NaiveDate>,
    pub to_date: Option<NaiveDate>,
    pub date: Option<NaiveDate>,
    pub project: Option<String>,
    pub round: Option<TimeDelta>,
}

impl ActivityFilter {
    fn matches(&self, a: &Activity) -> bool {
        let date = a.start.date();
        if let Some(d) = self.date {
            if date != d {
                return false;
            }
        }
        if let Some(from) = self.from_date {
            if date < from {
                return false;
            }
        }
        if let Some(to) = self.to_date {
            if date > to {
                return false;
            }
        }
        if let Some(p) = &self.project {
            if &a.project != p {
                return false;
            }
        }
        true
    }
}

fn rounded(a: &Activity, interval: Option<TimeDelta>) -> Activity {
    match interval {
        Some(i) => Activity {
            start: round_datetime(a.start, i),
            end: a.end.map(|e| round_datetime(e, i)),
            project: a.project.clone(),
            description: a.description.clone(),
        },
        None => a.clone(),
    }
}

/// Rounds, sorts (by start), filters and truncates the activities.
fn filtered_activities(activities: &[&Activity], filter: &ActivityFilter) -> Vec<Activity> {
    let mut acts: Vec<Activity> = activities.iter().map(|a| rounded(a, filter.round)).collect();
    acts.sort_by_key(|a| a.start);
    let mut acts: Vec<Activity> = acts.into_iter().filter(|a| filter.matches(a)).collect();
    if let Some(n) = filter.number_of_activities {
        if acts.len() > n {
            acts.drain(0..acts.len() - n);
        }
    }
    acts
}

/// Distinct (description, project) pairs, most recent first.
fn descriptions_and_projects(activities: &[&Activity]) -> Vec<(String, String)> {
    let mut acts: Vec<&Activity> = activities.to_vec();
    acts.sort_by_key(|a| a.start);
    let mut result: Vec<(String, String)> = Vec::new();
    for a in acts.iter().rev() {
        let pair = (a.description.clone(), a.project.clone());
        if !result.contains(&pair) {
            result.push(pair);
        }
    }
    result
}

fn sum_durations<'a, I: Iterator<Item = &'a Activity>>(acts: I, now: NaiveDateTime) -> TimeDelta {
    acts.fold(TimeDelta::zero(), |acc, a| acc + a.duration(now))
}

// ---------------------------------------------------------------------------
// mutating commands

fn stop_running(lines: &mut [Line], time: NaiveDateTime) {
    let now = now();
    for line in lines.iter_mut() {
        if let Some(a) = line.as_activity_mut() {
            if !a.is_stopped() {
                a.stop(time);
                line.modified = true;
                let a = line.as_activity().unwrap();
                println!(
                    "Stopped activity: \"{}\" ({}) started at {} ({})",
                    a.description,
                    a.project,
                    a.start.format(DATETIME_FORMAT),
                    format_duration(a.duration(now))
                );
            }
        }
    }
}

fn start_activity(lines: &mut Vec<Line>, project: String, description: String, time: NaiveDateTime) {
    let activity = Activity::start(project, description, time);
    println!(
        "Started activity: \"{}\" ({}) at {}",
        activity.description,
        activity.project,
        activity.start.format(DATETIME_FORMAT)
    );
    lines.push(Line::for_activity(activity));
}

pub fn start(path: &str, project: &str, description: &str, time: Option<NaiveDateTime>) -> Result<()> {
    let mut lines = storage::get_file_content_or_empty(path);
    let time = time.unwrap_or_else(now);
    stop_running(&mut lines, time);
    start_activity(&mut lines, project.to_string(), description.to_string(), time);
    storage::write_to_file(path, &lines)
}

pub fn stop(path: &str, time: Option<NaiveDateTime>) -> Result<()> {
    let mut lines = storage::get_file_content(path)?;
    let time = time.unwrap_or_else(now);
    stop_running(&mut lines, time);
    storage::write_to_file(path, &lines)
}

pub fn cancel(path: &str) -> Result<()> {
    let lines = storage::get_file_content(path)?;
    let mut kept: Vec<Line> = Vec::new();
    for line in lines {
        match line.as_activity() {
            Some(a) if !a.is_stopped() => {
                println!(
                    "Canceled activity: \"{}\" ({}) started at {}",
                    a.description,
                    a.project,
                    a.start.format(DATETIME_FORMAT)
                );
            }
            _ => kept.push(line),
        }
    }
    storage::write_to_file(path, &kept)
}

pub fn change(
    path: &str,
    description: Option<&str>,
    project: Option<&str>,
    time: Option<NaiveDateTime>,
) -> Result<()> {
    let mut lines = storage::get_file_content(path)?;
    if description.is_some() || project.is_some() || time.is_some() {
        for line in lines.iter_mut() {
            if let Some(a) = line.as_activity_mut() {
                if !a.is_stopped() {
                    if let Some(d) = description {
                        a.description = d.to_string();
                    }
                    if let Some(p) = project {
                        a.project = p.to_string();
                    }
                    if let Some(t) = time {
                        a.start = t;
                    }
                    line.modified = true;
                    let a = line.as_activity().unwrap();
                    println!(
                        "Changed activity: \"{}\" ({}) started at {}",
                        a.description,
                        a.project,
                        a.start.format(DATETIME_FORMAT)
                    );
                }
            }
        }
    }
    storage::write_to_file(path, &lines)
}

pub fn continue_last(
    path: &str,
    number: usize,
    description: Option<&str>,
    project: Option<&str>,
    time: Option<NaiveDateTime>,
) -> Result<()> {
    let mut lines = storage::get_file_content(path)?;
    let (desc, proj) = {
        let activities = storage::activities_with_warnings(&lines);
        let pairs = descriptions_and_projects(&activities);
        if pairs.is_empty() {
            bail!("No activity has been started before.");
        }
        if number > pairs.len() {
            bail!("Less than {} distinct activities have been logged yet", number);
        }
        let index = number.min(pairs.len() - 1);
        pairs[index].clone()
    };
    let desc = description.map(|d| d.to_string()).unwrap_or(desc);
    let proj = project.map(|p| p.to_string()).unwrap_or(proj);
    let time = time.unwrap_or_else(now);
    stop_running(&mut lines, time);
    start_activity(&mut lines, proj, desc, time);
    storage::write_to_file(path, &lines)
}

// ---------------------------------------------------------------------------
// reporting commands

pub fn list(path: &str, filter: &ActivityFilter, do_group: bool) -> Result<()> {
    let lines = storage::get_file_content(path)?;
    let activities = storage::activities_with_warnings(&lines);
    let acts = filtered_activities(&activities, filter);
    if acts.is_empty() {
        println!("No activity to display");
        return Ok(());
    }
    let now = now();
    let mut table = Table::new(vec!["Started", "Stopped", "Description", "Project", "Duration"]);
    if filter.date.is_some() {
        table.add_rows(acts.iter().map(|a| activity_row(a, now, false)).collect());
    } else if do_group {
        let mut current_date: Option<NaiveDate> = None;
        let mut rows: Vec<Row> = Vec::new();
        let mut group_acts: Vec<&Activity> = Vec::new();
        for a in &acts {
            let d = a.start.date();
            if current_date != Some(d) {
                if let Some(cd) = current_date {
                    let total = sum_durations(group_acts.iter().copied(), now);
                    table.add_group(
                        format!("{}\t{}", cd.format("%Y-%m-%d"), format_duration(total)),
                        std::mem::take(&mut rows),
                    );
                    group_acts.clear();
                }
                current_date = Some(d);
            }
            rows.push(activity_row(a, now, false));
            group_acts.push(a);
        }
        if let Some(cd) = current_date {
            let total = sum_durations(group_acts.iter().copied(), now);
            table.add_group(
                format!("{}\t{}", cd.format("%Y-%m-%d"), format_duration(total)),
                rows,
            );
        }
    } else {
        table.add_rows(acts.iter().map(|a| activity_row(a, now, true)).collect());
    }
    print!("{}", table.render());
    Ok(())
}

fn activity_row(a: &Activity, now: NaiveDateTime, with_start_date: bool) -> Row {
    let started = if with_start_date {
        a.start.format(DATETIME_FORMAT).to_string()
    } else {
        a.start.format("%H:%M").to_string()
    };
    let stopped = match a.end {
        None => "-".to_string(),
        Some(e) => {
            if a.starts_and_ends_on_different_days() {
                e.format(DATETIME_FORMAT).to_string()
            } else {
                e.format("%H:%M").to_string()
            }
        }
    };
    let style = if !a.is_stopped() {
        Style::Green
    } else if a.starts_and_ends_on_different_days() {
        Style::Yellow
    } else {
        Style::None
    };
    Row::styled(
        vec![
            started,
            stopped,
            a.description.clone(),
            a.project.clone(),
            format_duration(a.duration(now)),
        ],
        style,
    )
}

pub fn current(path: &str) -> Result<()> {
    let lines = storage::get_file_content(path)?;
    let activities = storage::activities_with_warnings(&lines);
    let running: Vec<&Activity> = activities.iter().copied().filter(|a| !a.is_stopped()).collect();
    if running.is_empty() {
        println!("No Activity is currently running");
        return Ok(());
    }
    let now = now();
    let mut table = Table::new(vec!["Started At", "Description", "Project", "Duration"]);
    table.add_rows(
        running
            .iter()
            .map(|a| {
                Row::new(vec![
                    a.start.format(DATETIME_FORMAT).to_string(),
                    a.description.clone(),
                    a.project.clone(),
                    format_duration(a.duration(now)),
                ])
            })
            .collect(),
    );
    print!("{}", table.render());
    Ok(())
}

fn descriptions_table(pairs: &[(usize, (String, String))]) -> String {
    let mut table = Table::new(vec![" #", "Description", "Project"]);
    table.add_rows(
        pairs
            .iter()
            .map(|(i, (d, p))| Row::new(vec![format!("[{}]", i), d.clone(), p.clone()]))
            .collect(),
    );
    table.render()
}

pub fn last(path: &str, number: usize) -> Result<()> {
    let lines = storage::get_file_content(path)?;
    let activities = storage::activities_with_warnings(&lines);
    let pairs: Vec<(usize, (String, String))> = descriptions_and_projects(&activities)
        .into_iter()
        .enumerate()
        .take(number)
        .collect();
    if pairs.is_empty() {
        println!("No activities have been tracked yet");
        return Ok(());
    }
    print!("{}", descriptions_table(&pairs));
    Ok(())
}

pub fn search(path: &str, term: &str) -> Result<()> {
    let lines = storage::get_file_content(path)?;
    let activities = storage::activities_with_warnings(&lines);
    let term = term.to_lowercase();
    let pairs: Vec<(usize, (String, String))> = descriptions_and_projects(&activities)
        .into_iter()
        .enumerate()
        .filter(|(_, (d, p))| d.to_lowercase().contains(&term) || p.to_lowercase().contains(&term))
        .collect();
    if pairs.is_empty() {
        println!("No matching activities found");
        return Ok(());
    }
    print!("{}", descriptions_table(&pairs));
    Ok(())
}

pub fn projects(path: &str, current_only: bool, no_quotes: bool) -> Result<()> {
    let lines = storage::get_file_content(path)?;
    let activities = storage::activities_with_warnings(&lines);
    let mut projects: Vec<&str> = activities
        .iter()
        .filter(|a| !current_only || !a.is_stopped())
        .map(|a| a.project.as_str())
        .collect();
    projects.sort();
    projects.dedup();
    for p in projects {
        if no_quotes {
            println!("{}", p);
        } else {
            println!("\"{}\"", p);
        }
    }
    Ok(())
}

pub fn report(path: &str, filter: &ActivityFilter) -> Result<()> {
    let lines = storage::get_file_content(path)?;
    let activities = storage::activities_with_warnings(&lines);
    let acts = filtered_activities(&activities, filter);
    let now = now();

    let mut by_project: BTreeMap<&str, BTreeMap<&str, TimeDelta>> = BTreeMap::new();
    let mut total = TimeDelta::zero();
    for a in &acts {
        let d = a.duration(now);
        total += d;
        let entry = by_project
            .entry(a.project.as_str())
            .or_default()
            .entry(a.description.as_str())
            .or_insert_with(TimeDelta::zero);
        *entry += d;
    }

    // (indent, name, duration)
    let mut rows: Vec<(usize, String, String, bool)> = Vec::new();
    for (p, descs) in &by_project {
        let p_total = descs.values().fold(TimeDelta::zero(), |acc, d| acc + *d);
        rows.push((0, p.to_string(), format_duration(p_total), true));
        for (d, dur) in descs {
            rows.push((4, d.to_string(), format_duration(*dur), false));
        }
    }
    let total_str = format_duration(total);
    let name_width = rows
        .iter()
        .map(|(i, n, _, _)| i + n.chars().count())
        .chain(std::iter::once("Total".len()))
        .max()
        .unwrap_or(0);
    let dur_width = rows
        .iter()
        .map(|(_, _, d, _)| d.chars().count())
        .chain(std::iter::once(total_str.chars().count()))
        .max()
        .unwrap_or(0);

    println!();
    for (indent, name, dur, is_project) in &rows {
        let line = format!(
            "{}{} {}",
            " ".repeat(*indent),
            dots(name, name_width - indent),
            right_align(dur, dur_width)
        );
        if *is_project {
            println!("{}", Style::Bold.paint(&line));
        } else {
            println!("{}", line);
            // a blank line follows the last description of a project
        }
        if !*is_project {
            // check whether next row is a project (or end) to print separator
        }
    }
    // Reformat: print groups with trailing blank lines
    let _ = rows;
    Ok(())
}

fn dots(name: &str, width: usize) -> String {
    let mut s = String::from(name);
    for _ in name.chars().count()..width {
        s.push('.');
    }
    s
}

fn right_align(s: &str, width: usize) -> String {
    let mut out = String::new();
    for _ in s.chars().count()..width {
        out.push(' ');
    }
    out.push_str(s);
    out
}

pub fn status(path: &str, project: Option<&str>) -> Result<()> {
    let lines = storage::get_file_content(path)?;
    let activities = storage::activities_with_warnings(&lines);
    let filter = ActivityFilter {
        project: project.map(|p| p.to_string()),
        ..Default::default()
    };
    let acts = filtered_activities(&activities, &filter);
    let now = now();
    let today = today();
    let week_start = today - TimeDelta::days(today.weekday().num_days_from_monday() as i64);
    let month_start = today.with_day(1).unwrap_or(today);

    let running = acts.iter().find(|a| !a.is_stopped());
    let today_total = sum_durations(acts.iter().filter(|a| a.start.date() == today), now);
    let week_total = sum_durations(
        acts.iter().filter(|a| a.start.date() >= week_start && a.start.date() <= today),
        now,
    );
    let month_total = sum_durations(
        acts.iter().filter(|a| a.start.date() >= month_start && a.start.date() <= today),
        now,
    );

    let mut out = String::new();
    out.push_str(&Style::Dimmed.paint("\n ======="));
    match project {
        Some(p) => {
            out.push_str(&Style::Italic.paint(" Status for project: "));
            out.push_str(&Style::Bold.paint(p));
        }
        None => {
            out.push_str(&Style::Italic.paint(" Status for "));
            out.push_str(&Style::Bold.paint("ALL"));
            out.push_str(&Style::Italic.paint(" projects "));
        }
    }
    out.push_str(&Style::Dimmed.paint(" ======= \n"));
    out.push_str(&Style::DimmedItalic.paint("\n  NOW: "));
    match running {
        Some(a) => {
            out.push_str(&Style::BoldGreen.paint(&a.description));
            if project.is_none() {
                out.push_str(&Style::DimmedItalic.paint(" on "));
                out.push_str(&Style::Italic.paint(&a.project));
            }
            out.push_str(&Style::Dimmed.paint(" ...... "));
            out.push_str(&Style::Bold.paint(&format_duration(a.duration(now))));
            out.push_str(&Style::Dimmed.paint("\n\n"));
        }
        None => {
            out.push_str(&Style::Bold.paint(" NO Activity\n\n"));
        }
    }
    for (label, total) in [
        ("Today", today_total),
        ("Current week", week_total),
        ("Current month", month_total),
    ] {
        out.push_str(&Style::Italic.paint(" "));
        out.push_str(&Style::DimmedItalic.paint(&format!(" {} ", dots(label, 30))));
        out.push_str(&Style::Bold.paint(&format_duration(total)));
        out.push_str(&Style::Italic.paint("\n"));
    }
    out.push('\n');
    print!("{}", out);
    Ok(())
}

pub fn check(path: &str) -> Result<()> {
    let lines = storage::get_file_content(path)?;
    let errors: Vec<&Line> = lines.iter().filter(|l| l.activity.is_err()).collect();
    if errors.is_empty() {
        println!("All lines in the file have been successfully parsed as activities.");
        return Ok(());
    }
    println!("Found {} line(s) with parsing errors", errors.len());
    for l in errors {
        let err = l.activity.as_ref().err().unwrap();
        println!("\n{}\n  -> {} (Line: {})", l.text, err, l.line_number);
    }
    Ok(())
}

pub fn sanity(path: &str) -> Result<()> {
    let lines = storage::get_file_content(path)?;
    let now = now();
    let mut acts: Vec<(usize, &Activity)> = lines
        .iter()
        .filter_map(|l| l.as_activity().map(|a| (l.line_number, a)))
        .collect();
    acts.sort_by_key(|(_, a)| a.start);

    let mut found = false;
    for (i, (line_number, a)) in acts.iter().enumerate() {
        let mut messages: Vec<&str> = Vec::new();
        if a.duration(now) < TimeDelta::zero() {
            messages.push("Activity has negative duration");
        }
        let overlaps = acts[..i]
            .iter()
            .any(|(_, other)| other.end.map_or(false, |e| e > a.start));
        if overlaps {
            messages.push("Activity started before another activity ended");
        }
        if !messages.is_empty() {
            found = true;
            for m in messages {
                println!("{}", m);
            }
            println!(
                "{} (Started: {}, Ended: {}, Line: {})\n",
                a.description,
                a.start.format(DATETIME_FORMAT),
                a.end
                    .map(|e| e.format(DATETIME_FORMAT).to_string())
                    .unwrap_or_else(|| "--".to_string()),
                line_number
            );
        }
    }
    if !found {
        println!("No unusual activities.");
    }
    Ok(())
}

pub fn edit(path: &str, editor: Option<&str>) -> Result<()> {
    let editor = match editor {
        Some(e) => e,
        None => bail!("editor command is missing"),
    };
    std::process::Command::new(editor).arg(path).status()?;
    Ok(())
}
