fn build_app() -> App {
    let top = CmdDef {
        name: cli::APP_NAME,
        about: cli::APP_ABOUT,
        args: TOP_ARGS,
    };
    let subcommands = vec![
        CmdDef { name: "start", about: "starts a new activity", args: START_ARGS },
        CmdDef { name: "change", about: "changes the current activity", args: CHANGE_ARGS },
        CmdDef { name: "continue", about: "continues a previous activity", args: CONTINUE_ARGS },
        CmdDef { name: "stop", about: "stops all currently running activities", args: STOP_ARGS },
        CmdDef { name: "cancel", about: "cancels all currently running activities", args: &[] },
        CmdDef { name: "current", about: "lists all currently running activities", args: &[] },
        CmdDef { name: "list", about: "list recent activities", args: LIST_ARGS },
        CmdDef { name: "report", about: "reports duration of tracked activities", args: REPORT_ARGS },
        CmdDef { name: "last", about: "displays the descriptions and projects of recent activities", args: LAST_ARGS },
        CmdDef { name: "projects", about: "list all projects", args: PROJECTS_ARGS },
        CmdDef { name: "edit", about: "opens the activity log in an editor", args: EDIT_ARGS },
        CmdDef { name: "check", about: "checks file and reports parsing errors", args: &[] },
        CmdDef { name: "sanity", about: "checks sanity of bartib log", args: &[] },
        CmdDef { name: "search", about: "search for existing descriptions and projects", args: SEARCH_ARGS },
        CmdDef {
            name: "status",
            about: "shows current status and time reports for today, current week, and current month",
            args: STATUS_ARGS,
        },
    ];
    App::new(top, subcommands)
