        ArgDef::flag("today", None, "today", "show activities of the current day").conflicts(TODAY_CONFLICTS),
        ArgDef::flag("yesterday", None, "yesterday", "show yesterdays' activities").conflicts(YESTERDAY_CONFLICTS),
        ArgDef::flag("current_week", None, "current_week", "show activities of the current week")
            .conflicts(CURRENT_WEEK_CONFLICTS),
