            .conflicts(LAST_WEEK_CONFLICTS),
        ArgDef::opt("project", Some('p'), Some("project"), Some("PROJECT"), project_help),
    ]
}

const LIST_DATE_ARGS: [ArgDef; 8] = date_args("do list activities for this project only");
const REPORT_DATE_ARGS: [ArgDef; 8] = date_args("do report activities for this project only");

const TOP_ARGS: &[ArgDef] = &[ArgDef::opt(
    "file",
    Some('f'),
