)
.env("BARTIB_FILE")];

const START_ARGS: &[ArgDef] = &[description_arg().required(), project_arg().required(), time_arg()];
const CHANGE_ARGS: &[ArgDef] = &[description_arg(), project_arg(), time_arg()];
const CONTINUE_ARGS: &[ArgDef] = &[
    description_arg(),
    project_arg(),
    time_arg(),
    ArgDef::pos("NUMBER", "the number of the activity to continue (see subcommand `last`)").default("0"),
];
const STOP_ARGS: &[ArgDef] = &[time_arg()];
const EDIT_ARGS: &[ArgDef] = &[ArgDef::opt(
    "editor",
