)
.env("EDITOR")];
const LAST_ARGS: &[ArgDef] = &[ArgDef::opt(
    "number",
    Some('n'),
    Some("number"),
    Some("NUMBER"),
    "maximum number of lines to display",
)
.default("10")];
const LIST_ARGS: &[ArgDef] = &[
    LIST_DATE_ARGS[0],
    LIST_DATE_ARGS[1],
    LIST_DATE_ARGS[2],
    LIST_DATE_ARGS[3],
    LIST_DATE_ARGS[4],
    LIST_DATE_ARGS[5],
    LIST_DATE_ARGS[6],
    LIST_DATE_ARGS[7],
    ArgDef::flag("no_grouping", None, "no_grouping", "do not group activities by date in list"),
    ArgDef::opt("number", Some('n'), Some("number"), Some("NUMBER"), "maximum number of activities to display"),
    ArgDef::opt("round", None, Some("round"), None, ROUND_HELP),
];
const REPORT_ARGS: &[ArgDef] = &[
