const STATUS_ARGS: &[ArgDef] =
    &[ArgDef::opt("project", Some('p'), Some("project"), Some("PROJECT"), "show status for this project only")];

fn build_app() -> App {
    let top = CmdDef {
        name: cli::APP_NAME,
        about: cli::APP_ABOUT,
        args: TOP_ARGS,
    };
    let subcommands = vec![
        CmdDef { name: "start", about: "starts a new activity", args: START_ARGS },
        CmdDef { name: "change", about: "changes the current activity", args: CHANGE_ARGS },
        CmdDef { name: "continue", about: "continues a previous activity", args: CONTINUE_ARGS },
        CmdDef { name: "stop", about: "stops all currently running activities", args: STOP_ARGS },
        CmdDef { name: "cancel", about: "cancels all currently running activities", args: &[] },
        CmdDef { name: "current", about: "lists all currently running activities", args: &[] },
        CmdDef { name: "list", about: "list recent activities", args: LIST_ARGS },
        CmdDef { name: "report", about: "reports duration of tracked activities", args: REPORT_ARGS },
        CmdDef { name: "last", about: "displays the descriptions and projects of recent activities", args: LAST_ARGS },
        CmdDef { name: "projects", about: "list all projects", args: PROJECTS_ARGS },
        CmdDef { name: "edit", about: "opens the activity log in an editor", args: EDIT_ARGS },
        CmdDef { name: "check", about: "checks file and reports parsing errors", args: &[] },
        CmdDef { name: "sanity", about: "checks sanity of bartib log", args: &[] },
        CmdDef { name: "search", about: "search for existing descriptions and projects", args: SEARCH_ARGS },
        CmdDef {
            name: "status",
            about: "shows current status and time reports for today, current week, and current month",
            args: STATUS_ARGS,
        },
    ];
    App::new(top, subcommands)
}

fn main() {
    let args: Vec<String> = std::env::args_os()
        .skip(1)
        .map(|a| a.to_string_lossy().into_owned())
        .collect();
    let app = build_app();
    let matches = match app.parse(args) {
        Outcome::Matches(m) => m,
        Outcome::Info(text) => {
            let stdout = std::io::stdout();
            let mut lock = stdout.lock();
            let _ = writeln!(lock, "{}", text);
            let _ = lock.flush();
            std::process::exit(0);
        }
        Outcome::Failure(text) => {
            eprintln!("{}", text);
            std::process::exit(1);
        }
    };

    if let Err(e) = run(&matches) {
        eprintln!("Error: {:?}", e);
        std::process::exit(1);
    }
}

fn run(matches: &Matches) -> Result<()> {
    let (sub_name, sub) = match &matches.subcommand {
        Some((n, m)) => (n.as_str(), m.as_ref()),
        None => return Ok(()),
    };

    let file_name = match matches.value_of("file") {
        Some(f) => f.to_string(),
        None => bail!(
            "Please specify a file with your activity log either as -f option or as BARTIB_FILE environment variable"
        ),
    };

    match sub_name {
        "start" => {
            let time = parse_time_arg(sub);
            commands::start(
                &file_name,
                sub.value_of("project").unwrap_or(""),
                sub.value_of("description").unwrap_or(""),
                time,
            )
        }
        "change" => {
            let time = parse_time_arg(sub);
            commands::change(&file_name, sub.value_of("description"), sub.value_of("project"), time)
        }
        "continue" => {
            let number = parse_number_arg(sub.value_of("NUMBER")).unwrap_or(0);
            let time = parse_time_arg(sub);
            commands::continue_last(
                &file_name,
                number,
                sub.value_of("description"),
                sub.value_of("project"),
                time,
            )
        }
        "stop" => {
            let time = parse_time_arg(sub);
            commands::stop(&file_name, time)
        }
        "cancel" => commands::cancel(&file_name),
        "current" => commands::current(&file_name),
        "list" => {
            let mut filter = build_filter(sub);
            filter.number_of_activities = parse_number_arg(sub.value_of("number"));
            let do_group = !sub.is_present("no_grouping");
            commands::list(&file_name, &filter, do_group)
        }
        "report" => {
            let filter = build_filter(sub);
            commands::report(&file_name, &filter)
        }
        "last" => {
            let number = parse_number_arg(sub.value_of("number")).unwrap_or(10);
            commands::last(&file_name, number)
        }
        "projects" => commands::projects(&file_name, sub.is_present("current"), sub.is_present("no-quotes")),
        "edit" => commands::edit(&file_name, sub.value_of("editor")),
        "check" => commands::check(&file_name),
        "sanity" => commands::sanity(&file_name),
        "search" => commands::search(&file_name, sub.value_of("SEARCH_TERM").unwrap_or("")),
        "status" => commands::status(&file_name, sub.value_of("project")),
        _ => Ok(()),
    }
}

fn parse_time_arg(sub: &Matches) -> Option<NaiveDateTime> {
    let value = sub.value_of("time")?;
    match NaiveTime::parse_from_str(value, "%H:%M") {
        Ok(t) => Some(commands::today().and_time(t)),
        Err(e) => {
            println!(
                "Can not parse \"{}\" as time. Argument for -t/--time is ignored ({})",
                value, e
            );
            None
        }
    }
}

fn parse_number_arg(value: Option<&str>) -> Option<usize> {
    let value = value?;
    match value.parse::<usize>() {
        Ok(n) => Some(n),
        Err(_) => {
            println!(
                "Can not parse \"{}\" as number. Argument for -n/--number is ignored",
                value
            );
            None
        }
    }
}

fn parse_date_arg(value: Option<&str>, arg_display: &str) -> Option<NaiveDate> {
    let value = value?;
    match NaiveDate::parse_from_str(value, "%Y-%m-%d") {
        Ok(d) => Some(d),
        Err(e) => {
            println!(
                "Can not parse \"{}\" as date. Argument for {} is ignored ({})",
                value, arg_display, e
            );
            None
        }
    }
}

fn parse_round_arg(value: Option<&str>) -> Option<TimeDelta> {
    let value = value?;
    match activity::parse_round_interval(value) {
        Ok(r) => r,
        Err(()) => {
            println!(
                "Can not parse \"{}\" as duration. Argument for --round is ignored",
                value
            );
            None
        }
    }
}

fn build_filter(sub: &Matches) -> ActivityFilter {
    let mut filter = ActivityFilter {
        date: parse_date_arg(sub.value_of("date"), "-d/--date"),
        from_date: parse_date_arg(sub.value_of("from"), "--from"),
        to_date: parse_date_arg(sub.value_of("to"), "--to"),
        project: sub.value_of("project").map(|p| p.to_string()),
        round: parse_round_arg(sub.value_of("round")),
        ..Default::default()
    };
    let today = commands::today();
    if sub.is_present("today") {
        filter.date = Some(today);
    }
    if sub.is_present("yesterday") {
        filter.date = Some(today - TimeDelta::days(1));
    }
    if sub.is_present("current_week") {
        let monday = today - TimeDelta::days(today.weekday().num_days_from_monday() as i64);
        filter.from_date = Some(monday);
        filter.to_date = Some(monday + TimeDelta::days(6));
    }
    if sub.is_present("last_week") {
        let monday = today - TimeDelta::days(today.weekday().num_days_from_monday() as i64) - TimeDelta::days(7);
        filter.from_date = Some(monday);
        filter.to_date = Some(monday + TimeDelta::days(6));
    }
    filter
}
