//! Access to the current local time.

use std::os::raw::{c_char, c_int, c_long};
use std::time::{SystemTime, UNIX_EPOCH};

use chrono::{DateTime, NaiveDate, NaiveDateTime};

#[repr(C)]
struct Tm {
    tm_sec: c_int,
    tm_min: c_int,
    tm_hour: c_int,
    tm_mday: c_int,
    tm_mon: c_int,
    tm_year: c_int,
    tm_wday: c_int,
    tm_yday: c_int,
    tm_isdst: c_int,
    tm_gmtoff: c_long,
    tm_zone: *const c_char,
}

extern "C" {
    fn localtime_r(timep: *const i64, result: *mut Tm) -> *mut Tm;
}

/// The current local date and time (with sub-second precision).
pub fn now() -> NaiveDateTime {
    let (secs, nanos) = match SystemTime::now().duration_since(UNIX_EPOCH) {
        Ok(d) => (d.as_secs() as i64, d.subsec_nanos()),
        Err(e) => {
            let d = e.duration();
            (-(d.as_secs() as i64) - if d.subsec_nanos() > 0 { 1 } else { 0 }, if d.subsec_nanos() > 0 { 1_000_000_000 - d.subsec_nanos() } else { 0 })
        }
    };
    let utc = DateTime::from_timestamp(secs, nanos)
        .map(|d| d.naive_utc())
        .unwrap_or_default();

    let mut tm: Tm = unsafe { std::mem::zeroed() };
    let t: i64 = secs;
    let res = unsafe { localtime_r(&t, &mut tm) };
    if res.is_null() {
        return utc;
    }
    NaiveDate::from_ymd_opt(tm.tm_year + 1900, (tm.tm_mon + 1) as u32, tm.tm_mday as u32)
        .and_then(|d| d.and_hms_nano_opt(tm.tm_hour as u32, tm.tm_min as u32, tm.tm_sec.min(59) as u32, nanos))
        .unwrap_or(utc)
}
